CREATE TRIGGER IF NOT EXISTS b004_readonly_timetable_entries_insert BEFORE INSERT ON timetable_entries WHEN EXISTS(SELECT 1 FROM schedules s WHERE s.schedule_id=NEW.schedule_id AND s.status IN ('Published','Archived')) BEGIN SELECT RAISE(ABORT,'Official schedule entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS b004_invalidate_timetable_entries_insert BEFORE INSERT ON timetable_entries WHEN 1=1 BEGIN DELETE FROM schedule_validation_receipts WHERE schedule_id IN (NEW.schedule_id); END;
CREATE TRIGGER IF NOT EXISTS b004_readonly_timetable_entries_update BEFORE UPDATE ON timetable_entries WHEN EXISTS(SELECT 1 FROM schedules s WHERE s.schedule_id=OLD.schedule_id AND s.status IN ('Published','Archived')) OR EXISTS(SELECT 1 FROM schedules s WHERE s.schedule_id=NEW.schedule_id AND s.status IN ('Published','Archived')) BEGIN SELECT RAISE(ABORT,'Official schedule entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS b004_invalidate_timetable_entries_update BEFORE UPDATE ON timetable_entries WHEN 1=1 BEGIN DELETE FROM schedule_validation_receipts WHERE schedule_id IN (OLD.schedule_id,NEW.schedule_id); END;
CREATE TRIGGER IF NOT EXISTS b004_readonly_timetable_entries_delete BEFORE DELETE ON timetable_entries WHEN EXISTS(SELECT 1 FROM schedules s WHERE s.schedule_id=OLD.schedule_id AND s.status IN ('Published','Archived')) BEGIN SELECT RAISE(ABORT,'Official schedule entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS b004_invalidate_timetable_entries_delete BEFORE DELETE ON timetable_entries WHEN 1=1 BEGIN DELETE FROM schedule_validation_receipts WHERE schedule_id IN (OLD.schedule_id); END;
CREATE TRIGGER IF NOT EXISTS b004_readonly_exam_entries_insert BEFORE INSERT ON exam_entries WHEN EXISTS(SELECT 1 FROM schedules s WHERE s.schedule_id=NEW.schedule_id AND s.status IN ('Published','Archived')) BEGIN SELECT RAISE(ABORT,'Official schedule entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS b004_invalidate_exam_entries_insert BEFORE INSERT ON exam_entries WHEN 1=1 BEGIN DELETE FROM schedule_validation_receipts WHERE schedule_id IN (NEW.schedule_id); END;
CREATE TRIGGER IF NOT EXISTS b004_readonly_exam_entries_update BEFORE UPDATE ON exam_entries WHEN EXISTS(SELECT 1 FROM schedules s WHERE s.schedule_id=OLD.schedule_id AND s.status IN ('Published','Archived')) OR EXISTS(SELECT 1 FROM schedules s WHERE s.schedule_id=NEW.schedule_id AND s.status IN ('Published','Archived')) BEGIN SELECT RAISE(ABORT,'Official schedule entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS b004_invalidate_exam_entries_update BEFORE UPDATE ON exam_entries WHEN 1=1 BEGIN DELETE FROM schedule_validation_receipts WHERE schedule_id IN (OLD.schedule_id,NEW.schedule_id); END;
CREATE TRIGGER IF NOT EXISTS b004_readonly_exam_entries_delete BEFORE DELETE ON exam_entries WHEN EXISTS(SELECT 1 FROM schedules s WHERE s.schedule_id=OLD.schedule_id AND s.status IN ('Published','Archived')) BEGIN SELECT RAISE(ABORT,'Official schedule entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS b004_invalidate_exam_entries_delete BEFORE DELETE ON exam_entries WHEN 1=1 BEGIN DELETE FROM schedule_validation_receipts WHERE schedule_id IN (OLD.schedule_id); END;
CREATE TRIGGER IF NOT EXISTS b004_readonly_exam_room_allocations_insert BEFORE INSERT ON exam_room_allocations WHEN EXISTS(SELECT 1 FROM schedules s WHERE s.schedule_id=(SELECT schedule_id FROM exam_entries WHERE exam_entry_id=NEW.exam_entry_id) AND s.status IN ('Published','Archived')) BEGIN SELECT RAISE(ABORT,'Official schedule entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS b004_invalidate_exam_room_allocations_insert BEFORE INSERT ON exam_room_allocations WHEN 1=1 BEGIN DELETE FROM schedule_validation_receipts WHERE schedule_id IN ((SELECT schedule_id FROM exam_entries WHERE exam_entry_id=NEW.exam_entry_id)); END;
CREATE TRIGGER IF NOT EXISTS b004_readonly_exam_room_allocations_update BEFORE UPDATE ON exam_room_allocations WHEN EXISTS(SELECT 1 FROM schedules s WHERE s.schedule_id=(SELECT schedule_id FROM exam_entries WHERE exam_entry_id=OLD.exam_entry_id) AND s.status IN ('Published','Archived')) OR EXISTS(SELECT 1 FROM schedules s WHERE s.schedule_id=(SELECT schedule_id FROM exam_entries WHERE exam_entry_id=NEW.exam_entry_id) AND s.status IN ('Published','Archived')) BEGIN SELECT RAISE(ABORT,'Official schedule entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS b004_invalidate_exam_room_allocations_update BEFORE UPDATE ON exam_room_allocations WHEN 1=1 BEGIN DELETE FROM schedule_validation_receipts WHERE schedule_id IN ((SELECT schedule_id FROM exam_entries WHERE exam_entry_id=OLD.exam_entry_id),(SELECT schedule_id FROM exam_entries WHERE exam_entry_id=NEW.exam_entry_id)); END;
CREATE TRIGGER IF NOT EXISTS b004_readonly_exam_room_allocations_delete BEFORE DELETE ON exam_room_allocations WHEN EXISTS(SELECT 1 FROM schedules s WHERE s.schedule_id=(SELECT schedule_id FROM exam_entries WHERE exam_entry_id=OLD.exam_entry_id) AND s.status IN ('Published','Archived')) BEGIN SELECT RAISE(ABORT,'Official schedule entries are immutable'); END;
CREATE TRIGGER IF NOT EXISTS b004_invalidate_exam_room_allocations_delete BEFORE DELETE ON exam_room_allocations WHEN 1=1 BEGIN DELETE FROM schedule_validation_receipts WHERE schedule_id IN ((SELECT schedule_id FROM exam_entries WHERE exam_entry_id=OLD.exam_entry_id)); END;
CREATE TRIGGER IF NOT EXISTS b004_header_scope BEFORE UPDATE ON schedules WHEN EXISTS(SELECT 1 FROM schedule_snapshots p WHERE p.schedule_id=OLD.schedule_id) AND (NEW.term_id<>OLD.term_id OR NEW.schedule_type<>OLD.schedule_type OR NEW.config_id<>OLD.config_id OR NEW.version_no<>OLD.version_no) BEGIN SELECT RAISE(ABORT,'Version scope is immutable'); END;
CREATE TRIGGER IF NOT EXISTS b004_publish_context BEFORE UPDATE ON schedules WHEN NEW.status='Published' AND OLD.status<>'Published' AND (OLD.status<>'Generated' OR NOT EXISTS(SELECT 1 FROM schedule_snapshots p JOIN schedule_validation_receipts r ON r.schedule_id=p.schedule_id AND r.input_hash=p.input_hash WHERE p.schedule_id=OLD.schedule_id)) BEGIN SELECT RAISE(ABORT,'Publication requires a validated Generated snapshot and fresh review'); END;
CREATE TRIGGER IF NOT EXISTS b004_insert_official BEFORE INSERT ON schedules WHEN NEW.status IN ('Published','Archived') BEGIN SELECT RAISE(ABORT,'Official schedules must transition from Generated'); END;
CREATE TRIGGER IF NOT EXISTS b004_lifecycle BEFORE UPDATE ON schedules WHEN (OLD.status='Archived' AND NEW.status<>'Archived') OR (OLD.status='Published' AND NEW.status NOT IN ('Published','Archived')) OR (NEW.status='Archived' AND OLD.status NOT IN ('Published','Archived')) BEGIN SELECT RAISE(ABORT,'Official versions cannot return to editable states'); END;
CREATE TRIGGER IF NOT EXISTS b004_approval BEFORE UPDATE ON schedules WHEN OLD.status IN ('Published','Archived') AND ((NEW.approved_by<>OLD.approved_by OR (NEW.approved_by IS NULL AND OLD.approved_by IS NOT NULL) OR (NEW.approved_by IS NOT NULL AND OLD.approved_by IS NULL)) OR (NEW.published_at<>OLD.published_at OR (NEW.published_at IS NULL AND OLD.published_at IS NOT NULL) OR (NEW.published_at IS NOT NULL AND OLD.published_at IS NULL)) OR (NEW.generated_by<>OLD.generated_by OR (NEW.generated_by IS NULL AND OLD.generated_by IS NOT NULL) OR (NEW.generated_by IS NOT NULL AND OLD.generated_by IS NULL)) OR (NEW.generated_at<>OLD.generated_at OR (NEW.generated_at IS NULL AND OLD.generated_at IS NOT NULL) OR (NEW.generated_at IS NOT NULL AND OLD.generated_at IS NULL)) OR (NEW.solver_status<>OLD.solver_status OR (NEW.solver_status IS NULL AND OLD.solver_status IS NOT NULL) OR (NEW.solver_status IS NOT NULL AND OLD.solver_status IS NULL)) OR (NEW.objective_score<>OLD.objective_score OR (NEW.objective_score IS NULL AND OLD.objective_score IS NOT NULL) OR (NEW.objective_score IS NOT NULL AND OLD.objective_score IS NULL)) OR (NEW.run_seconds<>OLD.run_seconds OR (NEW.run_seconds IS NULL AND OLD.run_seconds IS NOT NULL) OR (NEW.run_seconds IS NOT NULL AND OLD.run_seconds IS NULL)) OR (NEW.config_id<>OLD.config_id OR (NEW.config_id IS NULL AND OLD.config_id IS NOT NULL) OR (NEW.config_id IS NOT NULL AND OLD.config_id IS NULL)) OR (NEW.term_id<>OLD.term_id OR (NEW.term_id IS NULL AND OLD.term_id IS NOT NULL) OR (NEW.term_id IS NOT NULL AND OLD.term_id IS NULL)) OR (NEW.schedule_type<>OLD.schedule_type OR (NEW.schedule_type IS NULL AND OLD.schedule_type IS NOT NULL) OR (NEW.schedule_type IS NOT NULL AND OLD.schedule_type IS NULL)) OR (NEW.version_no<>OLD.version_no OR (NEW.version_no IS NULL AND OLD.version_no IS NOT NULL) OR (NEW.version_no IS NOT NULL AND OLD.version_no IS NULL))) BEGIN SELECT RAISE(ABORT,'Official approval metadata is immutable'); END;
CREATE TRIGGER IF NOT EXISTS b004_delete_official BEFORE DELETE ON schedules WHEN OLD.status IN ('Published','Archived') BEGIN SELECT RAISE(ABORT,'Official version history cannot be deleted'); END;
COMMIT;
